    :return: The difference of the two numbers,str.
    >>> bigNum = BigNumCalculator()
    >>> bigNum.subtract("12345678901234567890", "98765432109876543210")
    '-86419753208641975320'
    """
    def to_digits(n):
        return [int(c) for c in n[::-1]]

    def compare_digits(d1, d2):
        """Compare two digit lists as numbers (1 if d1 > d2, -1 if d1 < d2, 0 if equal)"""
        if len(d1) > len(d2):
            return 1
        elif len(d1) < len(d2):
            return -1
        else:
            for di1, di2 in zip(d1, d2):
                if di1 > di2:
                    return 1
                elif di1 < di2:
                    return -1
            return 0

    def sub_digits(d1, d2):
        """Subtract d2 from d1 (assumes d1 >= d2) and return digit list"""
        result = []
        borrow = 0

        max_len = max(len(d1), len(d2))
        for i in range(max_len):
            v1 = d1[i] if i < len(d1) else 0
            v2 = d2[i] if i < len(d2) else 0

            val = v1 - v2 - borrow

            if val < 0:
                val += 10
                borrow = 1
            else:
                borrow = 0

            result.append(val)

        # Remove trailing zeros
        while len(result) > 1 and result[-1] == 0:
            result.pop()

        return result

